steps.script:
for il in tree.current_scene.find_children('*', 'ItemList', true, false):
	if not il.is_visible_in_tree():
		continue
	for i in il.item_count:
		if il.get_item_text(i).begins_with('Painboss'):
			var r = il.get_item_rect(i)
			var p = il.get_global_transform_with_canvas() * (r.position + r.size * 0.5)
			TouchInputAdapter.inject_tap(p)
			return true
return false

var br = tree.current_scene.get_node('BoardRoot')
var p = br.get_global_transform_with_canvas() * Vector2(1066.0, 2213.0)
TouchInputAdapter.inject_tap(p)
return true
